// frontend/src/App.js (Example, adapt to your template's main chat component)
import React, { useState } from 'react';
import MessageInput from './components/MessageInput'; // Adjust path if necessary
import MessageList from './components/MessageList';   // Adjust path if necessary
import './App.css'; // Assuming your main CSS is here

function App() {
  const [messages, setMessages] = useState([]); // State to hold all chat messages

  const handleSendMessage = async (text) => {
    // 1. Add user message to display immediately
    const newUserMessage = { sender: 'user', text: text, id: Date.now() };
    setMessages((prevMessages) => [...prevMessages, newUserMessage]);

    try {
      // 2. Send message to backend
      const response = await fetch('http://localhost:8000/chat', { // <-- IMPORTANT: Your backend URL
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ message: text }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      const agentResponseText = data.response; // Get the 'response' key from your FastAPI JSON

      // 3. Add agent's response to display
      const newAgentMessage = { sender: 'agent', text: agentResponseText, id: Date.now() + 1 };
      setMessages((prevMessages) => [...prevMessages, newAgentMessage]);

    } catch (error) {
      console.error('Error sending message to backend:', error);
      // Optional: Display an error message to the user in the chat
      setMessages((prevMessages) => [
        ...prevMessages,
        { sender: 'agent', text: 'Oops! Something went wrong. Please try again.', id: Date.now() + 2, error: true }
      ]);
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>PartSelect Chat Agent</h1>
      </header>
      <div className="chat-container">
        <MessageList messages={messages} /> {/* You'll need to create MessageList component */}
        <MessageInput onSendMessage={handleSendMessage} />
      </div>
    </div>
  );
}

export default App;
